/*{
  "DESCRIPTION": "Gentle falling snow for Christmas lights",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "bgColor", "TYPE": "color", "DEFAULT": [0.02, 0.05, 0.20, 1.0] },
    { "NAME": "snowColor", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 0.40 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.1, "MAX": 8.0, "DEFAULT": 2.00 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.5, "MAX": 10.0, "DEFAULT": 3.00 },
    { "NAME": "twinkle", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.25 }
  ]
}*/
float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = (RENDERSIZE.y < 2.0);
  // For rooflines, drive the same animation along the horizontal axis
  if (isLine) {
    uv.y = isf_FragNormCoord.x;
  }

  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // parameters tuned for small canvases
  const int COLS = 8;
  const int ROWS = 4;

  // grid scale increases with density to produce more flakes visually
  float gridScaleMul = 1.0 + density * 0.60;
  vec2 baseGrid = vec2(float(COLS), float(ROWS));
  float t = TIME * max(speed, 0.0);

  float accum = 0.0;

  for (int xi = 0; xi < COLS; xi++) {
    for (int yi = 0; yi < ROWS; yi++) {
      vec2 idx = vec2(float(xi), float(yi));

      // pseudo-random offsets per cell
      float rx = hash21(idx + vec2(0.13, 0.37));
      float ry = hash21(idx + vec2(0.71, 0.29));

      // base position in 0..1, repeat more when density is higher
      vec2 basePos = fract((idx + vec2(rx, ry)) / baseGrid * gridScaleMul);

      // falling motion: wrap y with time. Speed slightly varies by cell.
      float fallSpeed = 0.03 + rx * 0.07;
      float yPos = fract(basePos.y + t * fallSpeed);

      // horizontal subtle drift
      float drift = sin(t * (0.2 + ry * 0.8) + rx * 6.283185) * (0.02 + ry * 0.03);
      float xPos = basePos.x + drift;

      vec2 pos = vec2(xPos, yPos);
      pos = fract(pos); // wrap into 0..1

      // size varies per flake, influenced by scale and density
      float sizeBase = mix(0.012, 0.035, ry);
      float size = sizeBase * (1.0 / max(scale, 0.001)) * (1.0 + density * 0.12);

      // compute distance: for line displays, use 1D distance
      float dist;
      if (isLine) {
        dist = abs(uv.x - pos.x);
      } else {
        vec2 d = (uv - pos) * vec2(aspect, 1.0);
        dist = length(d);
      }

      // soft circular flake with smooth edge
      float flake = 1.0 - smoothstep(0.0, size, dist);

      // twinkle per flake
      float tw = 0.8 + 0.2 * sin(t * (1.0 + rx * 3.0) * (1.0 + twinkle * 8.0) + rx * 12.0);
      flake *= mix(1.0, tw, twinkle);

      // weight flakes so larger ones contribute more
      float weight = 0.6 + 0.8 * ry;
      accum += flake * weight * 0.35;
    }
  }

  // soft overall clamp
  accum = clamp(accum, 0.0, 1.0);
  // boost highlights a bit for night visibility
  float glow = pow(accum, 0.65);

  vec3 color = mix(bgColor.rgb, snowColor.rgb, glow);
  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "fire rising from the bottom",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.9, 0.5, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.4, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.6, 0.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.1, "MAX": 10.0, "DEFAULT": 1.5 },
    { "NAME": "flameHeight", "TYPE": "float", "MIN": 0.1, "MAX": 1.0, "DEFAULT": 0.8 },
    { "NAME": "turbulence", "TYPE": "float", "MIN": 0.0, "MAX": 2.0, "DEFAULT": 0.8 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // drive vertical axis; if the buffer is one-pixel tall, use x as the vertical axis
  float v = (RENDERSIZE.y < 2.0) ? uv.x : uv.y;
  float x = uv.x;

  // safe minimums to avoid division by zero
  float safeHeight = max(flameHeight, 0.01);
  float safeScale = max(scale, 0.01);

  // animated time
  float t = TIME * max(speed, 0.0);

  // multi-octave sine "fbm" turbulence along the horizontal axis
  float tsum = 0.0;
  float wsum = 0.0;
  for (int i = 1; i <= 4; i++) {
    float fi = pow(2.0, float(i));
    float w = 1.0 / fi;
    float phase = t * (0.4 + 0.1 * float(i));
    float off = v * (1.5 + 0.2 * float(i));
    tsum += sin((x * fi * safeScale * 6.28318) + phase + off) * w;
    wsum += w;
  }
  float turb = tsum / max(wsum, 0.0001); // -1..1
  turb = 0.5 + 0.5 * turb; // 0..1

  // horizontal spread gets narrower higher up
  float baseSpread = mix(0.22 * safeScale, 0.06 * safeScale, v);
  baseSpread = max(baseSpread, 0.005);

  // distance from center, account for aspect so wide displays look correct
  float dx = abs((x - 0.5) * aspect);
  float dnorm = dx / baseSpread;

  // horizontal mask: 1.0 at center, falls to 0 at edges
  float hmask = smoothstep(1.05, 0.0, dnorm);

  // vertical falloff controlled by flameHeight, with a soft top
  float vnorm = v / safeHeight;
  float vmask = clamp(1.0 - vnorm, 0.0, 1.0);

  // add flicker and turbulence influence
  float flick = 0.85 + 0.35 * sin(t * 3.0 + v * 10.0);
  float turbInfluence = mix(1.0, turb, min(turbulence, 2.0));
  float intensity = vmask * hmask * flick * turbInfluence;
  intensity = clamp(intensity, 0.0, 1.0);

  // color layering: outer (colorC) -> mid (colorB) -> core (colorA)
  vec3 colOuter = colorC.rgb;
  vec3 colMid = colorB.rgb;
  vec3 colCore = colorA.rgb;

  // smooth thresholds for color blending
  float midBlend = smoothstep(0.05, 0.65, intensity);
  float coreBlend = smoothstep(0.6, 1.0, intensity);

  vec3 baseCol = mix(colOuter, colMid, midBlend);
  vec3 finalCol = mix(baseCol, colCore, coreBlend);

  // add a soft additive glow based on intensity to simulate bright core
  vec3 glow = colCore * pow(intensity, 0.6) * 1.2;

  // slight upward motion streak: make brighter streaks that move up continuously
  float streak = smoothstep(0.0, 1.0, sin((v * 8.0 - t * 1.5) + turb * 6.28) * 0.5 + 0.5);
  finalCol += glow * (0.25 * streak);

  // final mix and clamp for high contrast and saturated look
  vec3 outColor = clamp(finalCol + glow * 0.2, 0.0, 1.0);

  gl_FragColor = vec4(outColor, 1.0);
}

/*{
  "DESCRIPTION": "Candy cane diagonal stripes scrolling",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 1.0, "MAX": 40.0, "DEFAULT": 10.0 },
    { "NAME": "softness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.10 },
    { "NAME": "angle", "TYPE": "float", "MIN": 0.0, "MAX": 360.0, "DEFAULT": 45.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  // If this is effectively a 1-pixel-tall strip, drive pattern along X so it still animates well
  if (RENDERSIZE.y < 2.0) {
    uv.y = uv.x;
  }

  // Convert angle to radians and build direction vector
  float ang = angle * (3.14159265 / 180.0);
  vec2 dir = vec2(cos(ang), sin(ang));

  // Position along the diagonal direction
  float pos = dot(uv, dir);

  // Ensure non-zero scale and softness
  float sc = max(scale, 0.001);
  float soft = max(softness, 0.001);

  // Scrolling offset (controls movement speed along the stripes)
  float offset = TIME * speed * 0.25;

  // Pattern coordinate and alternating band value with soft edges
  float pattern = fract(pos * sc - offset);
  float edge = 0.5 * soft; // half-width for smoothstep
  float band = smoothstep(0.5 - edge, 0.5 + edge, pattern);

  // Enhance contrast for a bright candy-cane look
  vec3 baseCol = mix(colorA.rgb, colorB.rgb, band);

  // Add a subtle glossy highlight that runs along each stripe to suggest rounded candy cane
  float gloss = pow(max(0.0, 1.0 - abs(fract((pos * sc - offset) * 2.0) - 0.5) * 2.0), 12.0);
  vec3 highlight = vec3(1.0, 1.0, 1.0) * (0.12 * gloss);

  // Slightly brighten the colored stripe more than the white stripe for richness
  float stripeTint = mix(1.0, 1.08, band); // tiny tint to colorA when band near 0
  vec3 color = baseCol * stripeTint + highlight * (1.0 - band * 0.5);

  // Final strong contrast clamp
  color = clamp(color, 0.0, 1.0);

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Smooth wash that fades between the chosen colours",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 0.3 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.1, "MAX": 8.0, "DEFAULT": 1.0 },
    { "NAME": "softness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.8 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  // Drive along x for most displays; for very short height (rooflines) keep it on x too.
  float coord = uv.x;
  float PI = 3.14159265;
  float TWO_PI = 6.28318530;

  // Slow moving phase across the model
  float phase = coord * scale + TIME * speed;

  // Base sinusoidal activations for up to three colours spaced in phase
  float a1 = 0.5 + 0.5 * sin(TWO_PI * phase + 0.0);
  float a2 = 0.5 + 0.5 * sin(TWO_PI * phase + 2.09439510); // +120 degrees
  float a3 = 0.5 + 0.5 * sin(TWO_PI * phase + 4.18879020); // +240 degrees

  // Map softness (0..1) to a sharpening exponent: low softness -> sharp transitions
  float sharp = mix(0.5, 6.0, 1.0 - softness);

  // Apply sharpening/softening
  a1 = pow(a1, sharp);
  a2 = pow(a2, sharp);
  a3 = pow(a3, sharp);

  // Combine based on how many colours the user provided
  vec3 col = vec3(0.0, 0.0, 0.0);
  if (NUMCOLORS == 1) {
    col = colorA.rgb;
  } else if (NUMCOLORS == 2) {
    // Use only a1 and a2
    float sum = a1 + a2 + 0.000001;
    float w1 = a1 / sum;
    float w2 = a2 / sum;
    col = w1 * colorA.rgb + w2 * colorB.rgb;
  } else {
    // Three or more colours: blend across A, B, C
    float sum = a1 + a2 + a3 + 0.000001;
    float w1 = a1 / sum;
    float w2 = a2 / sum;
    float w3 = a3 / sum;
    col = w1 * colorA.rgb + w2 * colorB.rgb + w3 * colorC.rgb;
  }

  // Ensure vivid output suitable for lights; slight gamma boost
  col = pow(col, vec3(0.95));

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Twinkling stars across the lights",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.8, 0.6, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.8, 0.9, 1.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 1.0 },
    { "NAME": "sparkleSize", "TYPE": "float", "MIN": 0.005, "MAX": 0.5, "DEFAULT": 0.06 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.1, "MAX": 8.0, "DEFAULT": 3.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  // aspect correction so stars look consistent on non-square canvases
  vec2 aspect = vec2(RENDERSIZE.x / max(RENDERSIZE.y, 1.0), 1.0);
  vec2 p = uv;
  // If this is a roofline (very short height), drive animation along x only
  bool isLine = (RENDERSIZE.y < 2.0);
  if (isLine) {
    p.y = 0.5;
  }

  const int N = 16;
  float accum = 0.0;
  vec3 colorAccum = vec3(0.0);

  for (int i = 0; i < N; i++) {
    float fi = float(i);
    // deterministic pseudo-random seeds per star
    float seed = fi * 12.9898;
    float hx = fract(sin(seed) * 43758.5453);
    float hy = fract(sin(seed + 78.233) * 96563.123);
    vec2 spos = vec2(hx, hy);
    if (isLine) {
      spos.y = 0.5;
    }
    // spread influenced by density
    spos.x = fract(spos.x * (1.0 + density * 3.0));

    // distance with aspect correction
    vec2 dp = (p - spos) * aspect;
    float d = length(dp);

    // star base shape (soft circular)
    float s = max(0.001, sparkleSize);
    float base = 1.0 - smoothstep(0.0, s, d);

    // twinkle modulation: each star has its own phase and frequency
    float phaseSeed = fract(sin(seed * 0.543 + 0.123) * 43758.5453);
    float freq = 0.5 + density * 2.0;
    float tw = 0.5 + 0.5 * sin(TIME * speed * (1.0 + phaseSeed * freq) * 6.2831853 + phaseSeed * 6.2831853);
    float shimmer = pow(max(0.0, tw), sharpness);

    // small bright core spike for sharp glints
    float spike = pow(max(0.0, 1.0 - d / (s * 0.25)), 8.0) * mix(0.25, 1.0, fract(phaseSeed * 4.0));

    float intensity = base * (0.35 + 0.65 * shimmer) + spike;

    // choose color from palette with slight variation per star
    vec3 c1 = mix(colorA.rgb, colorB.rgb, fract(phaseSeed * 2.1));
    vec3 c = mix(c1, colorC.rgb, smoothstep(0.0, 1.0, fract(phaseSeed * 3.0)));

    colorAccum += c * intensity;
    accum += intensity;
  }

  // normalize to keep overall brightness consistent as density changes
  float norm = max(0.0001, accum / float(N));
  vec3 outCol = colorAccum / norm;

  // clamp and apply mild gamma for vivid look
  outCol = clamp(outCol, 0.0, 1.0);
  outCol = pow(outCol, vec3(0.85));

  gl_FragColor = vec4(outCol, 1.0);
}

/*{
  "DESCRIPTION": "A repeating colored chase that runs along the roofline",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 0.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "count", "TYPE": "long", "MIN": 1, "MAX": 64, "DEFAULT": 8 },
    { "NAME": "width", "TYPE": "float", "MIN": 0.01, "MAX": 0.5, "DEFAULT": 0.12 },
    { "NAME": "softness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.25 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  // Drive along X for rooflines; if the buffer is very tall, still use X so the chase reads on a roofline.
  float pos = uv.x;

  // Safeguard for division and counts
  float fCount = max(float(count), 1.0);

  // Movement: speed controls how fast the chase marches; loop is seamless due to fract()
  float move = TIME * (speed * 0.25);

  // Each pulse occupies one segment out of fCount across X
  float seg = fract(pos * fCount - move);

  // Distance from center of a segment (0.5 is the center)
  float dist = abs(seg - 0.5);

  // Pulse width and edge softness
  float halfW = clamp(width * 0.5, 0.001, 0.5);
  float edge = clamp(softness, 0.0, 1.0) * halfW;

  // Intensity shaped by smoothstep for soft edges; peak at center
  float intensity = 1.0 - smoothstep(halfW - edge, halfW + edge, dist);

  // Add a small sheen that travels with the chase for a lively effect
  float sheen = 0.15 * sin( (pos * fCount - move) * 6.283185 + TIME * 6.283185 );
  intensity = clamp(intensity + sheen * intensity, 0.0, 1.0);

  // High contrast mixing between background and chase color
  vec3 col = mix(colorB.rgb, colorA.rgb, intensity);

  // Slight global dim to keep black truly off when background is chosen black
  float globalBoost = 1.0;
  col *= globalBoost;

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Swirling plasma for Christmas lights",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.2, "MAX": 6.0, "DEFAULT": 2.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // center and aspect-correct
  vec2 p = uv - vec2(0.5, 0.5);
  p.x *= aspect;
  // If this is a roofline (very short height), drive the animation along X
  if (RENDERSIZE.y < 2.0) {
    float x = uv.x - 0.5;
    p = vec2(x * aspect, x);
  }
  float t = TIME * speed;
  // polar coordinates for swirling
  float angle = atan(p.y, p.x);
  float radius = length(p) * scale;
  // layered swirling/plasma terms
  float swirl = angle + 1.5 * sin(radius * 3.0 - t * 0.5);
  float term1 = sin(swirl * 3.0 + t);
  float term2 = sin(radius * 6.0 - t * 0.8 + cos(p.x * 5.0 + t * 0.3));
  float term3 = sin(p.x * 10.0 + p.y * 7.0 + t * 0.6);
  float combined = (term1 + term2 + term3) * 0.3333333;
  float val = 0.5 + 0.5 * sin(combined * 3.14159265 + t * 0.2);
  // tighten contrast for bright holiday lights
  val = pow(abs(val), 0.9);
  // palette blend between three user colors
  float a = smoothstep(0.0, 0.5, val);
  float b = smoothstep(0.5, 1.0, val);
  vec3 col = mix(colorA.rgb, colorB.rgb, a);
  col = mix(col, colorC.rgb, b);
  // add a soft radial glow and subtle pulsing
  float glow = 0.6 / (0.2 + radius * radius * 6.0);
  col += glow * (0.5 + 0.5 * sin(t + radius * 8.0)) * vec3(1.0);
  // clamp and output opaque color
  col = clamp(col, 0.0, 1.0);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "rainbow sweeping across",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "bands", "TYPE": "float", "MIN": 1.0, "MAX": 12.0, "DEFAULT": 6.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.01, "MAX": 1.0, "DEFAULT": 0.5 },
    { "NAME": "brightness", "TYPE": "float", "MIN": 0.0, "MAX": 3.0, "DEFAULT": 1.0 }
  ]
}*/
vec3 hsv2rgb(vec3 c) {
  vec3 k = vec3(0.0, 2.0/3.0, 1.0/3.0);
  vec3 p = abs(fract(vec3(c.x) + k) * 6.0 - 3.0);
  return c.z * mix(vec3(1.0), clamp(p - vec3(1.0), 0.0, 1.0), c.y);
}

void main() {
  vec2 uv = isf_FragNormCoord;
  // choose primary axis so narrow displays still show the sweep
  float p = (RENDERSIZE.x < 2.0) ? uv.y : uv.x;

  // moving position across the axis
  float pos = p * bands - TIME * speed * 0.2;
  float f = fract(pos); // 0..1 along each band

  // triangular stripe shape (0..0.5), scale to 0..1
  float tri = (0.5 - abs(f - 0.5)) * 2.0;

  // smooth the stripe edges using sharpness (edge in 0..1)
  float edge = clamp(sharpness, 0.01, 1.0);
  float mask = smoothstep(0.0, edge, tri);

  // hue varies across each band so the sweep shows full rainbow
  float hue = f; // 0..1
  vec3 rainbow = hsv2rgb(vec3(hue, 1.0, 1.0));

  // subtle vertical modulation so tall displays have depth, but keep effect visible on 1-pixel tall lines
  float vmod = mix(1.0, smoothstep(0.0, 1.0, uv.y), step(2.0, RENDERSIZE.y));

  vec3 col = rainbow * mask * vmod * brightness;

  // allow a simple tint from the user-chosen colorA
  col *= colorA.rgb;

  // keep fully opaque
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Synchronized pulsing Christmas lights on a steady beat",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.0, "MAX": 2.0, "DEFAULT": 0.8 },
    { "NAME": "spread", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.2 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  float PI = 3.14159265;

  // Determine how many palette slots to place across the x axis
  float slots = max(1.0, float(NUMCOLORS));
  float freq = slots * (1.0 + spread * 10.0);

  // Triangle blending function for soft stripes
  float tri(in float x) {
    float f = fract(x);
    return max(0.0, 1.0 - abs(f - 0.5) * 2.0);
  }

  // Base color distribution across the strand/canvas (mapped along x)
  float k = uv.x * freq;
  float w0 = tri(k + 0.0);
  float w1 = tri(k + 0.3333333);
  float w2 = tri(k + 0.6666667);
  float wsum = w0 + w1 + w2 + 0.0001;
  vec3 baseCol = (colorA.rgb * w0 + colorB.rgb * w1 + colorC.rgb * w2) / wsum;

  // Global steady beat with optional slight phase spread across the line
  float phaseOffset = (uv.x - 0.5) * spread * 0.5; // small per-pixel offset
  float beatRaw = 0.5 + 0.5 * cos(2.0 * PI * (TIME * speed + phaseOffset));
  float pulse = pow(max(0.0, beatRaw), 1.0 + sharpness * 3.0);

  // Keep a little ambient so lights never vanish completely unless pulse is very low
  float ambient = 0.12;
  vec3 finalCol = baseCol * (ambient + (1.0 - ambient) * pulse);

  gl_FragColor = vec4(finalCol, 1.0);
}

