/*{
  "DESCRIPTION": "A stylized American flag waving",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.750, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.125, 0.5, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "waveAmp", "TYPE": "float", "MIN": 0.0, "MAX": 0.2, "DEFAULT": 0.035 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  // If the canvas is a roofline (very short), drive the vertical animation along x
  if (RENDERSIZE.y < 2.0) {
    uv.y = isf_FragNormCoord.x;
  }

  // Flag geometry constants (normalized to full canvas = 1.0 height)
  float stripes = 13.0;
  float cantonW = 0.40; // union width as fraction of flag length
  float cantonH = 7.0 / 13.0; // union height as fraction of flag height

  // Waving: multiple harmonics for a pleasing continuous motion
  float TWO_PI = 6.283185;
  float freq = 1.25;
  float t = TIME * speed;
  float wave = sin((uv.x) * freq * TWO_PI + t) * waveAmp
             + 0.5 * sin((uv.x) * (freq * 2.0) * TWO_PI + t * 0.7) * (waveAmp * 0.6);

  // Apply vertical displacement to produce wavy horizontal stripes
  vec2 v = uv;
  v.y += wave;

  // Keep v.y within 0..1 so stripes wrap neatly and don't sample outside
  v.y = clamp(v.y, 0.0, 1.0);

  // Determine stripe color: top stripe should be red (colorA)
  float sIndex = floor(v.y * stripes);
  float parity = mod(sIndex, 2.0);
  float isRed = 1.0 - parity; // 1.0 for red stripes, 0.0 for white
  vec3 stripeCol = mix(colorB.rgb, colorA.rgb, isRed);

  // Start with stripes as base
  vec3 col = stripeCol;

  // Canton (blue field) overlays stripes on the upper-left
  if (uv.x < cantonW && uv.y < cantonH) {
    // Base canton color (blue)
    col = colorC.rgb;

    // Compute local coordinates inside the canton [0..1]
    vec2 local = vec2(uv.x / cantonW, uv.y / cantonH);
    local = clamp(local, vec2(0.0), vec2(1.0));

    // Create a star grid approximating the 50-star pattern using alternating rows
    float rows = 9.0;
    float cols = 6.0;

    // Determine row index to offset every other row
    float rowIdx = floor(local.y * rows);
    float rowOffset = mod(rowIdx, 2.0) * 0.5 / cols;

    // Cell coordinates within the repeating grid
    vec2 cell = fract(vec2(local.x * cols + rowOffset, local.y * rows));
    vec2 d = cell - vec2(0.5);

    // Star shape by distance to cell center
    float starRadius = 0.22;
    float aa = 0.04;
    float dist = length(d);
    float star = 1.0 - smoothstep(starRadius - aa, starRadius + aa, dist);

    // Slightly boost some stars for variety using a secondary finer grid
    vec2 cell2 = fract(vec2(local.x * 5.0 + 0.25, local.y * 9.0));
    vec2 d2 = cell2 - vec2(0.5);
    float star2 = 1.0 - smoothstep(0.20 - 0.03, 0.20 + 0.03, length(d2));

    float starsMask = clamp(max(star, star2), 0.0, 1.0);

    // Overlay white stars (colorB) onto the canton
    col = mix(col, colorB.rgb, starsMask);
  }

  // Slight bloom along stripe crests for richer look (subtle lighting)
  float light = clamp(0.5 + 0.5 * sin((uv.x * 3.0 * TWO_PI) + t * 0.7), 0.0, 1.0);
  float highlight = 0.06 * light;
  col += highlight * (isRed * 0.6 + (1.0 - isRed) * 0.2);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Spooky green fog drifting",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.12, 1.00, 0.25, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.00, 0.00, 0.00, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.1, "MAX": 8.0, "DEFAULT": 1.5 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.6 }
  ]
}*/
float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
float noise21(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (vec2(3.0, 3.0) - 2.0 * f);
  float a = hash21(i + vec2(0.0, 0.0));
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
float fbm(vec2 p) {
  float v = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 5; i++) {
    v += amp * noise21(p * freq);
    freq *= 2.0;
    amp *= 0.5;
  }
  return v;
}
void main() {
  vec2 uv = isf_FragNormCoord;
  // Drive main motion along X; if canvas is essentially a roofline, keep it readable along X.
  vec2 coord = uv;
  if (RENDERSIZE.y < 2.0) {
    // When very short vertically, map variation into X so it reads across the strand
    coord.y = uv.x;
  }
  // Feature scale and animated drift
  float s = max(scale, 0.1);
  vec2 p = (coord - vec2(0.5, 0.5)) * s * 3.0;
  // Primary horizontal drift
  p.x += TIME * (0.12 * speed);
  // Subtle vertical flow for layers
  p.y += TIME * 0.04;
  // Layered fog
  float base = fbm(p + vec2(0.0, 0.0));
  float layer = fbm(p * 1.7 + vec2(5.2, -3.1) + base * 2.0);
  float detail = fbm(p * 3.2 - vec2(2.3, 1.7));
  // Combine layers into a soft, moving density map
  float raw = mix(base, layer, 0.6) * 0.8 + detail * 0.2;
  // Make fog more concentrated toward mid tones and controlled by density slider
  float thresholdLow = 0.35 - density * 0.25;
  float thresholdHigh = 0.70 - density * 0.35;
  float fog = smoothstep(thresholdLow, thresholdHigh, raw);
  // Add wispy bands that drift with time for spooky movement
  float bands = 0.5 + 0.5 * sin((coord.y * 6.0 + raw * 4.0) - TIME * speed * 0.6);
  fog *= mix(0.8, 1.2, pow(bands, 1.8));
  fog = clamp(fog, 0.0, 1.0);
  // Color the fog: colorA is the eerie green, colorB is the dark background
  vec3 col = mix(colorB.rgb, colorA.rgb, pow(fog, 1.2));
  // Boost contrast for visibility on lights
  col *= mix(0.6, 1.6, fog);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A spinning tunnel you fly into",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.1, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 0.2, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.1, "MAX": 12.0, "DEFAULT": 4.0 },
    { "NAME": "twist", "TYPE": "float", "MIN": 0.0, "MAX": 8.0, "DEFAULT": 2.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  // When the canvas is very short (a roofline), drive the same animation along X
  if (RENDERSIZE.y < 2.0) {
    uv.y = uv.x;
  }

  // Keep aspect ratio so tunnel looks circular
  float aspect = RENDERSIZE.x / max(1.0, RENDERSIZE.y);
  vec2 p = (uv - vec2(0.5, 0.5)) * vec2(aspect, 1.0) * 2.0;

  float eps = 0.0001;
  float r = length(p) + eps;
  float a = atan(p.y, p.x); // angle in radians

  // Motion parameters
  float t = TIME;
  float sp = speed;
  float sc = max(0.1, scale);
  float tw = twist;

  // Spin increases as we "fly" deeper (r smaller -> stronger twist)
  float spin = t * sp * 1.6 + tw / (r + 0.08);

  // Spiral and radial waves combine to make arms and rings that move inward
  float spiral = sin(a * 6.0 + spin); // 6 arms around the tunnel
  float radial = sin((1.0 / (r + 0.06)) * sc + t * sp * 3.0);

  // Combine waves and sharpen contrasts for bright, saturated bands
  float combined = spiral * 0.6 + radial * 0.8;
  float band = smoothstep(-0.15, 0.15, combined); // main bright bands
  float bandSharp = pow(band, 1.2);

  // Moving thin rings (pulses) for a sense of travel
  float ringPhase = fract((1.0 / (r + 0.06)) * sc + t * sp * 2.0);
  float ringPulse = smoothstep(0.58, 0.62, ringPhase);

  // Radial falloff so center is bright and edges dark (gives perspective)
  float centerFade = 1.0 - smoothstep(0.0, 1.4, r);
  centerFade = pow(centerFade, 0.7);

  // Add subtle streaks along the twist direction for motion lines
  float streak = pow(max(0.0, cos(spin * 4.0) * (0.8 - r)), 2.0);

  // Mix the two user colors according to the wave pattern
  vec3 baseColor = mix(colorA.rgb, colorB.rgb, 0.5 + 0.5 * sin(combined * 3.14159));

  // Final brightness: combine banding, ring pulses, center glow and streaks
  float brightness = clamp(centerFade * (0.6 + 0.9 * bandSharp) + 1.2 * ringPulse + 1.0 * streak, 0.0, 3.0);

  // Boost saturation and contrast for night-time display
  vec3 col = pow(baseColor, vec3(0.9)) * brightness;

  // Clamp and output opaque color
  col = clamp(col, 0.0, 1.0);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Ocean waves rolling with bright foam crests",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.02, 0.05, 0.30, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.00, 0.40, 0.70, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.00, 1.00, 1.00, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 0.80 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.20, "MAX": 8.0, "DEFAULT": 2.00 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  // choose a secondary coordinate that uses x for rooflines (very short Y)
  float useY = (RENDERSIZE.y < 2.0) ? uv.x : uv.y;

  // parameters
  const float PI = 3.14159265;
  float s = max(scale, 0.001);
  float t = TIME * speed;

  // aspect compensation so waves look natural on non-square layouts
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);

  // primary horizontal position, scaled and wrapped for seamless tiling
  float x = uv.x * s * aspect;

  // layered rolling waves (two main layers + fine ripples)
  float layer1 = sin((x * 1.0 + t * 0.60) * (2.0 * PI) + sin(useY * 6.0) * 0.45);
  float layer2 = sin((x * 1.6 + t * 0.90) * (2.0 * PI * 0.6) + cos(useY * 8.0) * 0.30);
  float ripples = sin((x * 10.0 + t * 2.5) + useY * 20.0) * 0.08;

  // combine and normalize to 0..1
  float wave = layer1 * 0.60 + layer2 * 0.40;
  float waveNorm = 0.5 + 0.5 * wave + ripples;
  waveNorm = clamp(waveNorm, 0.0, 1.0);

  // dynamic crest threshold to keep motion lively and loopable
  float crestBase = 0.62;
  float crestMod = 0.06 * sin(TIME * 0.12);
  float crestLevel = crestBase + crestMod;

  // sharpness derived from scale so finer scales have crisper crests
  float sharp = max(0.01, 0.08 / s);

  // foam mask for bright crests
  float foam = smoothstep(crestLevel - sharp, crestLevel + sharp, waveNorm);
  // emphasize the very tips
  float foamTip = pow(foam, 0.6);

  // base color gradient between deep and mid water depending on wave height
  vec3 baseCol = mix(colorA.rgb, colorB.rgb, smoothstep(0.0, 1.0, waveNorm));

  // boost brightness on ridges for strong night-time contrast
  float brightness = 0.35 + 0.65 * (0.4 + 0.6 * waveNorm);
  vec3 col = baseCol * brightness;

  // add foam color on crests (additive highlight for sparkling)
  col = mix(col, colorC.rgb, foamTip * 0.90);
  col += colorC.rgb * foam * 0.20;

  // final punch contrast and clamp
  col = clamp(col, 0.0, 1.0);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Slow lava lamp blobs",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.2, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.8, 0.1, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.6, 0.0, 0.6, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 0.25 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.3, "MAX": 2.0, "DEFAULT": 1.0 },
    { "NAME": "softness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.5 },
    { "NAME": "blobCount", "TYPE": "long", "MIN": 1, "MAX": 8, "DEFAULT": 5 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  // Drive along X when the render is a 1-pixel-tall line
  if (RENDERSIZE.y < 2.0) {
    uv.y = uv.x;
  }
  // Aspect to keep blob shapes pleasing on different canvases
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  vec2 scu = vec2(uv.x, uv.y);
  scu.x = (scu.x - 0.5) * aspect + 0.5;

  const int MAX_BLOBS = 8;
  const float PI = 3.14159265;
  // Slow, long-period motion — 60s base loop scaled by speed
  float basePeriod = 60.0;
  float t = TIME * speed * (2.0 * PI / basePeriod);

  // Parameters derived from user controls
  float s = clamp(scale, 0.3, 2.0);
  float soft = clamp(softness, 0.0, 1.0);
  int count = int(clamp(float(blobCount), 1.0, 8.0));

  // Compute additive gaussian-like metaball field
  float field = 0.0;
  for (int i = 0; i < MAX_BLOBS; i++) {
    if (i >= count) {
      break;
    }
    // Evenly place base positions across X, jitter Y slightly
    float fi = float(i);
    float fc = float(count);
    vec2 base = vec2((fi + 0.5) / fc, 0.5 + 0.08 * sin(t * 0.6 + fi * 2.1));

    // Each blob orbits slowly with small different phases for organic motion
    float angle = t * (0.6 + 0.12 * fi) + fi * 1.9;
    vec2 motion = vec2(cos(angle), sin(angle * 0.7 + fi * 1.3)) * (0.10 * s);

    // Blob position in screen uv
    vec2 pos = base + motion;

    // Adjust for aspect so blobs stay round
    vec2 d = vec2((scu.x - pos.x) , (scu.y - pos.y));
    d.x *= 1.0; // already accounted by scu.x

    float radius = mix(0.20, 0.06, clamp((s - 0.3) / 1.7, 0.0, 1.0));
    radius *= (1.0 + 0.15 * sin(t * 0.3 + fi * 2.7)); // gentle breathing

    // Gaussian contribution (smoothly blends and merges)
    float contrib = exp(- (d.x * d.x + d.y * d.y) / max(0.0001, radius * radius));
    field += contrib;
  }

  // Normalize field to a useful range and apply softness
  float fieldScaled = field * (0.6 + soft * 2.0);
  float m = clamp(fieldScaled, 0.0, 1.0);

  // Palette: three-way blend tuned for saturated lava-lamp look
  vec3 colAB = mix(colorA.rgb, colorB.rgb, smoothstep(0.0, 0.6, m));
  vec3 col = mix(colAB, colorC.rgb, smoothstep(0.3, 0.95, m));

  // Add outer glow rim for stronger contrast
  float rim = smoothstep(0.02, 0.0, length(vec2(scu.x - 0.5, scu.y - 0.5))) * 0.15;
  col += rim * (0.6 * (1.0 - m));

  // Punchier output for night-time displays
  col = pow(col, vec3(0.9)); // slight contrast boost

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Alternating flashes between the first two chosen colors",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.01, "MAX": 1.0, "DEFAULT": 0.6 },
    { "NAME": "segments", "TYPE": "long", "MIN": 1, "MAX": 32, "DEFAULT": 1 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;

  // Primary axis for the pattern: use X so rooflines read correctly.
  float axis = uv.x;

  // Ensure segments as a float and never below 1.0
  float segs = max(1.0, float(segments));

  // Which segment this pixel falls into (0..segs-1)
  float segIndex = floor(axis * segs);

  // Alternate phase by parity so neighboring segments flash opposite each other
  float parity = mod(segIndex, 2.0);

  // Oscillator: 2*pi * TIME * speed, parity adds pi to invert every other segment
  const float TWO_PI = 6.28318531;
  const float PI = 3.14159265;
  float phase = TIME * speed * TWO_PI + parity * PI;

  // Sine-based beat for smooth continuous flashing
  float beat = sin(phase);

  // Use sharpness to control transition width: small -> crisp flashes
  float sh = clamp(sharpness, 0.01, 1.0);
  float t = smoothstep(-sh, sh, beat);

  // Mix between the two user colors
  vec3 color = mix(colorB.rgb, colorA.rgb, t);

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "green streaks falling like digital rain",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.0, "MAX": 8.0, "DEFAULT": 3.0 },
    { "NAME": "streakWidth", "TYPE": "float", "MIN": 0.001, "MAX": 0.2, "DEFAULT": 0.02 }
  ]
}*/
float hashf(float n) {
  return fract(sin(n) * 43758.5453);
}
void main() {
  vec2 uv = isf_FragNormCoord;
