  vec3 streakTint = colorB.rgb * (1.0 + 0.6 * accum);
  vec3 base = colorA.rgb;
  vec3 col = mix(base, streakTint, clamp(accum, 0.0, 1.0));

  gl_FragColor = vec4(col, 1.0);
}

/*{
