    { "NAME": "count", "TYPE": "long", "MIN": 1, "MAX": 8, "DEFAULT": 3 },
    { "NAME": "size", "TYPE": "float", "MIN": 0.3, "MAX": 8.0, "DEFAULT": 2.0 }
  ]
