void main() {
  vec2 uv = isf_FragNormCoord;
  // Primary axis: use X so line displays and rooflines read correctly
  float axis = uv.x;
  // Time and global pulse (0..1) - slow, smooth, continuous
  float t = TIME * speed;
  float globalPulse = 0.5 + 0.5 * sin(t * 6.2831853);
