/*{
  "DESCRIPTION": "Colorful fireworks bursting with rings and sparkling dots",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.2, 0.1, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.9, 0.1, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.2, 0.6, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "bursts", "TYPE": "long", "MIN": 1, "MAX": 12, "DEFAULT": 6 }
  ]
}*/
float hash21(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
vec2 hash22(vec2 p) {
  return vec2(hash21(p + vec2(1.0, 0.0)), hash21(p + vec2(0.0, 1.0)));
}
void main() {
  vec2 uv = isf_FragNormCoord;
  // For rooflines, drive animation along x when height is tiny
  vec2 p = uv;
  if (RENDERSIZE.y < 2.0) {
    p.y = uv.x;
  }
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  const int MAX_BURSTS = 12;
  vec3 accum = vec3(0.0);
  const float PI = 3.14159265;
  const float TWO_PI = 6.2831853;
  for (int i = 0; i < MAX_BURSTS; i++) {
    if (i >= int(bursts)) {
      break;
    }
    float fi = float(i);
    // seed positions, bias to upper half for bursts
    float cx = hash21(vec2(fi * 12.989, 78.233));
    float cy = hash21(vec2(fi * 39.346, 11.135));
    vec2 center = vec2(cx, 0.25 + 0.6 * cy);
    float phase = hash21(vec2(fi * 5.23, 95.32));
    // cycle per burst, repeats smoothly
    float cycle = fract(TIME * speed * 0.25 + phase);
    float duration = 0.45;
    if (cycle < duration) {
      float localT = cycle / duration; // 0..1 for this burst's life
      // randomized final radius and thickness
      float radBase = 0.12 + 0.45 * hash21(vec2(fi, 3.21));
      float radius = localT * radBase;
      float thickness = 0.02 * (0.4 + 0.9 * hash21(vec2(fi, 7.0)));
      // distance in aspect-correct space
      vec2 d = (p - center) * vec2(aspect, 1.0);
      float dist = length(d);
      // bright expanding ring
      float ring = smoothstep(radius + thickness, radius - thickness, dist);
      // small bright core at earliest moment
      float core = smoothstep(0.01, 0.0, dist) * smoothstep(0.15, 0.0, 1.0 - localT);
      // sparkling dots arranged around the ring
      float angle = atan(d.y, d.x);
      float segF = floor((angle + PI) / TWO_PI * 18.0);
      float dotSeed = hash21(vec2(segF, fi * 7.0));
      float dotRadius = radius * (0.85 + 0.45 * dotSeed);
      float dot = smoothstep(0.03, 0.0, abs(dist - dotRadius));
      dot *= dotSeed;
      // additional radial spikes (subtle)
      float spikes = pow(max(0.0, cos(angle * (3.0 + 6.0 * hash21(vec2(fi, 2.0))) + phase * 6.2831853)), 8.0);
      spikes *= smoothstep(radius + 0.03, radius - 0.02, dist);
      // life-based brightness envelope (bright early, fades)
      float lifeBright = (1.0 - localT);
      lifeBright = pow(lifeBright, 1.2);
      // color selection per burst from the three user colors
      float mixA = hash21(vec2(fi, 1.0));
      float mixB = hash21(vec2(fi, 2.0));
      vec3 burstCol = mix(colorA.rgb, colorB.rgb, mixA);
      burstCol = mix(burstCol, colorC.rgb, mixB);
      // combine elements
      float intensity = (ring * 1.0 + dot * 0.9 + core * 1.6 + spikes * 0.6) * lifeBright;
      accum += burstCol * intensity * 1.8;
    }
  }
  // small global twinkle to suggest distant sparks
  float tw = hash21(uv * 234.5 + vec2(TIME * 0.5));
  float tiny = smoothstep(0.995, 1.0, tw) * 0.6;
  vec3 twCol = mix(colorB.rgb, colorC.rgb, hash21(uv * 12.3));
  accum += twCol * tiny;
  // tone mapping and clamp
  accum = clamp(accum, 0.0, 1.0);
  gl_FragColor = vec4(accum, 1.0);
}

/*{
  "DESCRIPTION": "warm candle flicker",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.85, 0.35, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.2, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 3.0, "DEFAULT": 1.0 },
    { "NAME": "flicker", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.7 }
  ]
}*/
float hash12(vec2 p) {
  return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}
float noise22(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash12(i + vec2(0.0, 0.0));
  float b = hash12(i + vec2(1.0, 0.0));
  float c = hash12(i + vec2(0.0, 1.0));
  float d = hash12(i + vec2(1.0, 1.0));
  vec2 u = f * f * (vec2(3.0, 3.0) - 2.0 * f);
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
void main() {
  vec2 uv = isf_FragNormCoord;
  float safeH = max(RENDERSIZE.y, 1.0);
  float aspect = RENDERSIZE.x / safeH;
  float isThin = (RENDERSIZE.y < 2.0) ? 1.0 : 0.0;

  // choose axis along which the flame rises: normally y, on very thin buffers use x
  float along = mix(uv.y, uv.x, isThin);
  // perpendicular coordinate (small across the flame)
  float perp = mix((uv.x - 0.5) * aspect * scale, (uv.y - 0.5) * aspect * scale, isThin);

  // time and noisy flicker
  float t = TIME * (0.8 + speed * 1.2);
  float nA = noise22(vec2(t * 0.9, 4.2));
  float nB = noise22(vec2(t * 2.3, 9.7));
  float pulse = 0.5 + 0.5 * sin(TIME * 6.0 * speed + hash12(vec2(TIME, 1.0)) * 6.28318);
  float flickNoise = mix(nA, nB, 0.5);
  float flickVal = mix(1.0 - 0.45 * flicker, 1.0 + 0.35 * flicker, pulse) * (0.85 + 0.3 * flickNoise);

  // flame geometry
  float flameHeight = clamp(0.22 * scale, 0.05, 0.9);
  float ynorm = clamp(along / flameHeight, 0.0, 1.0);

  // width shrinks upward; add subtle horizontal wobble from noise
  float wobble = 0.08 * noise22(vec2(along * 6.0, t * 0.7));
  float width = mix(0.28 + wobble, 0.03 + wobble * 0.2, ynorm) * scale;
  width = max(width, 0.001);

  // core shape: lateral falloff and vertical fade
  float d = abs(perp) / width;
  float core = 1.0 - clamp(d, 0.0, 1.0);
  float verticalFade = 1.0 - pow(ynorm, 1.6);
  float shape = core * verticalFade;

  // small upward bright tongues from faster noise
  float tongue = smoothstep(0.6, 0.0, fract(noise22(vec2(along * 10.0, t * 2.5)) + 0.5 * ynorm)) * 0.6;
  float brightness = (shape + 0.4 * tongue) * flickVal;
  brightness = clamp(brightness, 0.0, 1.6);

  // color blend from inner (colorA) to outer (colorB) with height influence
  float colorMixFactor = clamp(ynorm * 0.9 + (1.0 - core) * 0.3, 0.0, 1.0);
  vec3 flameCol = mix(colorA.rgb, colorB.rgb, colorMixFactor);

  // soft halo/glow around the flame
  float glow = exp(-abs(perp) * 10.0) * (0.7 + 0.7 * (1.0 - ynorm)) * flickVal;
  vec3 glowCol = mix(colorA.rgb * 0.8, colorB.rgb * 0.7, 0.7);

  vec3 outCol = flameCol * (brightness * 1.5) + glowCol * (glow * 0.9);

  // small ambient spill so it reads on dark backgrounds
  outCol += 0.02 * flickVal * colorB.rgb;

  outCol = clamp(outCol, vec3(0.0), vec3(1.0));
  gl_FragColor = vec4(outCol, 1.0);
}

/*{
  "DESCRIPTION": "Spinning barber pole for Christmas lights",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 20.0, "DEFAULT": 3.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.8 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  float height = RENDERSIZE.y;
  // rotation angle (radians)
  float angle = TIME * speed * 6.2831853;
  // center coordinates
  vec2 p = uv - vec2(0.5, 0.5);

  // stripe coordinate value in 0..1
  float val;
  if (height < 2.0) {
    // 1D line (roofline): simulate rotation as lateral motion along x
    float offset = TIME * speed * 0.25;
    val = fract((uv.x + offset) * scale);
  } else {
    // 2D: rotate coordinates around center to spin the barber pole
    float c = cos(angle);
    float s = sin(angle);
    vec2 rp = vec2(p.x * c - p.y * s, p.x * s + p.y * c);
    // use the rotated x to create diagonal stripes
    val = fract(rp.x * scale + 0.5);
  }

  // sharpness mapping: 1.0 = crisp, 0.0 = very soft
  float sh = clamp(sharpness, 0.001, 1.0);
  float transWidth = (1.0 - sh) * 0.45; // transition half-width
  // create high-contrast stripe between 0..1
  float stripe = smoothstep(0.5 - transWidth, 0.5 + transWidth, val);

  // base color mix between two user colors
  vec3 col = mix(colorA.rgb, colorB.rgb, stripe);

  // small glossy highlight along stripe edges for depth
  float edge = max(0.005, 0.02 * (1.0 - sh));
  float d = abs(val - 0.5);
  float spec = clamp((edge - d) / edge, 0.0, 1.0);
  // tint the highlight toward white and keep it subtle
  col = mix(col, vec3(1.0), spec * 0.35);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "raindrops making ripples",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.2, 0.6, 1.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.9, 0.5, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 8.0, "DEFAULT": 3.0 },
    { "NAME": "drops", "TYPE": "float", "MIN": 1.0, "MAX": 12.0, "DEFAULT": 6.0 },
    { "NAME": "softness", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.6 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  vec3 bg = colorC.rgb;
  vec3 outCol = bg;

  // Safety for render size based arithmetic
  float rsx = max(RENDERSIZE.x, 1.0);
  float rsy = max(RENDERSIZE.y, 1.0);

  // Drive ripples along X for very short buffers (rooflines)
  bool isLine = (RENDERSIZE.y < 2.0);

  // Parameters
  float t = TIME * speed;
  float countF = max(1.0, drops);
  int MAX_DROPS = 12;

  // Simple hash
  float hash1(float n) {
    return fract(sin(n) * 43758.5453123);
  }

  // Loop with constant bounds; only first int(countF) drops are active
  for (int i = 0; i < MAX_DROPS; i++) {
    if (i >= int(countF)) break;
    float fi = float(i);

    // Per-drop randomization
    float base = fi * 12.9898;
    float rx = hash1(base + 0.1234);
    float ry = hash1(base + 4.5678);
    float phase = hash1(base + 8.9012);

    // Period and radius scale per drop (avoid dividing by zero; speed >= 0.1)
    float period = mix(1.4, 3.6, hash1(base + 3.3333)) / speed;
    float maxRadiusNormalized = mix(0.12, 0.9, hash1(base + 6.7777)) * scale;

    // Map normalized radius to UV space taking render aspect into account
    // Use larger of dimensions so ripples look similar on narrow and wide buffers
    float diag = max(rsx, rsy);
    float maxRadius = maxRadiusNormalized * (diag > 0.0 ? (1.0 / diag) * min(rsx, rsy) : 1.0);

    // Compute this drop's repeating age (0..period)
    float startOffset = phase * period;
    float age = mod(TIME + startOffset, period);
    float nAge = age / period; // 0..1

    // Drop position in UV
    vec2 pos = vec2(rx, ry);

    // Distance: radial on 2D, absolute along X on 1D lines
    float dist;
    if (isLine) {
      dist = abs(uv.x - rx);
      // normalize distances for line to approximate screen-scale similar to 2D
      dist *= rsx / max(rsx, rsy);
    } else {
      dist = distance(uv, pos);
    }

    // Wave ring: outward moving radius
    float ringRadius = nAge * maxRadius;

    // Ring sharpness and decay
    float ringSharp = mix(8.0, 40.0, softness); // higher => thinner rings
    float decay = mix(1.5, 6.0, softness); // spatial decay

    // Ring shape (Gaussian-like) centered at distance == ringRadius
    float d = abs(dist - ringRadius);
    float ring = exp(- (d * ringSharp) * (d * ringSharp));

    // Age envelope: rings fade with time
    float ageEnv = pow(max(0.0, 1.0 - nAge), 1.2);

    // Central splash: bright short-lived core when age is small
    float core = 0.0;
    float coreRadius = maxRadius * 0.12;
    if (nAge < 0.25) {
      float c = smoothstep(coreRadius, 0.0, dist) * (1.0 - nAge * 4.0);
      core = c;
    }

    // Combine intensities and color mix
    float intensityRing = ring * ageEnv * (1.0 / max(1.0, decay * dist + 0.0001));
    float intensityCore = core * 1.6;

    // Color contributions: core uses colorA, ring uses colorB
    outCol += colorB.rgb * intensityRing * 1.6;
    outCol += colorA.rgb * intensityCore * 1.8;
  }

  // Slight glow and clamp
  outCol = clamp(outCol, 0.0, 1.0);

  gl_FragColor = vec4(outCol, 1.0);
}

