/*{
  "DESCRIPTION": "Aurora borealis curtains of flowing light",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.0, 0.8, 0.3, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 0.2, 1.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.6, 0.0, 0.9, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "curtains", "TYPE": "long", "MIN": 1, "MAX": 12, "DEFAULT": 6 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.2, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "softness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.5 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  // choose motion axis: normally vertical curtains (vary along y), but for 1-pixel tall buffers use x
  bool thin = (RENDERSIZE.y < 2.0);
  float major = thin ? uv.x : uv.y;   // position along the curtain (motion direction)
  float minor = thin ? uv.y : uv.x;   // cross-curtain axis (width)
  float t = TIME * speed;
  int maxIter = 12;
  float curtainsF = max(1.0, float(curtains));
  // parameters controlling look
  float globalScale = max(0.001, scale);
  float soft = clamp(softness, 0.0, 1.0);
  vec3 accum = vec3(0.0);
  // base frequency for vertical waviness
  float waveFreq = 1.0 + 0.6 * globalScale;
  // loop over possible curtain ribbons (constant bound)
  for (int i = 0; i < 12; i++) {
    if (i >= curtains) {
      continue;
    }
    // center of this ribbon, tiled across 0..1
    float idx = float(i);
    float center = (idx + 0.5) / curtainsF;
    // local coordinate across ribbon, wrapped so ribbons tile naturally
    float local = fract(minor * curtainsF) ; // 0..1 across each ribbon cell
    float dx = abs(local - 0.5); // distance from center of ribbon cell (0..0.5)
    // ribbon width scaled by user scale
    float baseWidth = 0.22 / globalScale; // nominal half-width
    // apply softness to edges
    float edge0 = baseWidth * (1.0 - 0.6 * soft);
    float edge1 = baseWidth * (1.0 + 0.6 * soft);
    float band = 1.0 - smoothstep(edge0, edge1, dx);
    // vertical waviness / flowing curtains
    float phase = t * (0.4 + 0.6 * float(i) / curtainsF) + idx * 1.17;
    float w = sin((major * 6.28318 * waveFreq) + phase) * 0.5 + 0.5; // 0..1
    // make brighter crests and softer troughs
    float waveMask = pow(w, 0.6 + 0.8 * (1.0 - soft));
    // slight horizontal drift per ribbon to simulate folds
    float drift = sin(major * 6.28318 * (0.5 + 0.1 * float(i)) + phase * 0.7) * 0.08;
    // color blend across the curtain using major position and wave
    float colorBlend = smoothstep(0.0, 1.0, major * (1.0 + 0.2 * sin(phase * 0.6)) + drift);
    vec3 c1 = colorA.rgb;
    vec3 c2 = colorB.rgb;
    vec3 c3 = colorC.rgb;
    vec3 col = mix(c1, c2, colorBlend);
    col = mix(col, c3, smoothstep(0.15, 0.85, w));
    // intensity and soft glow
    float intensity = band * (0.5 + 1.0 * waveMask);
    // add a subtle vertical halo based on distance from center to soften look
    float halo = exp(-12.0 * dx * dx / max(0.0001, baseWidth * baseWidth)) * (0.3 + 0.7 * waveMask);
    accum += col * intensity + col * halo * 0.15;
  }
  // global contrast and clamp
  vec3 color = clamp(accum, vec3(0.0), vec3(1.0));
  // boost saturation for night display
  float lum = dot(color, vec3(0.2126, 0.7152, 0.0722));
  vec3 sat = mix(vec3(lum), color, 1.2);
  gl_FragColor = vec4(sat, 1.0);
}

/*{
  "DESCRIPTION": "Comet circling with a long tail",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.5, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "tailLength", "TYPE": "float", "MIN": 0.1, "MAX": 6.0, "DEFAULT": 3.0 },
    { "NAME": "headSize", "TYPE": "float", "MIN": 0.001, "MAX": 0.5, "DEFAULT": 0.03 },
    { "NAME": "softness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.5 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  float TWO_PI = 6.28318531;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  float angSpeed = speed * 0.25 * TWO_PI; // controls orbital period
  float theta = TIME * angSpeed;

  // clamp user params into safe ranges
  float tLen = clamp(tailLength, 0.1, 6.28318531);
  float hSize = max(headSize, 0.001);
  float soft = clamp(softness, 0.0, 1.0);

  vec3 col = vec3(0.0, 0.0, 0.0);

  if (RENDERSIZE.y < 2.0) {
    // single-row / roofline: project the orbit so motion is visible along X
    // center X at 0.5, use a horizontal excursion
    float radiusX = 0.45;
    float cometX = 0.5 + cos(theta) * radiusX;
    // motion direction along x:
    float dxdt = -sin(theta) * radiusX * angSpeed;
    float movingRight = step(0.0, dxdt); // 1.0 when moving right, 0.0 when moving left

    // head intensity (1D distance)
    float headDist = abs(uv.x - cometX);
    float head = smoothstep(hSize * 1.5, 0.0, headDist);

    // tail: measure how far behind along x the pixel is
    // behindVal positive when pixel is behind comet in motion direction
    float behindVal = (cometX - uv.x) * (movingRight * 1.0 + (1.0 - movingRight) * -1.0);
    float tailRange = tLen * 0.08; // interpret tailLength as screen fraction scale here
    tailRange = max(tailRange, 0.01);
    float tnorm = clamp(behindVal / tailRange, 0.0, 1.0);
    float tail = pow(1.0 - tnorm, 2.0);
    // radial falloff for any vertical deviation (small line height)
    float radialFall = exp(-abs(uv.y - 0.5) * 30.0);
    tail *= radialFall * (1.0 - soft * 0.7);

    // color mix: head is colorA, tail is colorB
    col += colorB.rgb * tail;
    col += colorA.rgb * head * 1.6;
  } else {
    // full 2D circular orbit
    // transform coordinates so a circle looks round regardless of aspect
    vec2 centered = (uv - vec2(0.5, 0.5)) * vec2(aspect, 1.0);
    float radius = 0.35 * min(aspect, 1.0);
    vec2 cometPos = vec2(cos(theta), sin(theta)) * radius;
    float r = length(centered);
    float angleP = atan(centered.y, centered.x);

    // how far behind the pixel is, in radians (0..TWO_PI)
    float dtheta = mod(theta - angleP + TWO_PI, TWO_PI);

    // head brightness based on distance to comet core
    float headDist = distance(centered, cometPos);
    float head = smoothstep(hSize * 1.5, 0.0, headDist);

    // tail radial thickness
    float tailWidth = hSize * (1.0 + 6.0 * (1.0 - soft));
    tailWidth = max(tailWidth, 0.001);

    float radialDiff = abs(r - radius);
    float tailRadial = smoothstep(tailWidth, 0.0, radialDiff);

    // angular falloff along orbit: stronger near the comet, fading with angle
    float tailAngular = 1.0 - smoothstep(0.0, tLen, dtheta);
    float dnorm = clamp(dtheta / tLen, 0.0, 1.0);
    float tail = tailAngular * tailRadial * pow(1.0 - dnorm, 2.0);

    // subtle inner glow of the tail closer to the orbit center
    float innerGlow = smoothstep(radius * 0.7, radius * 0.3, r) * 0.2;

    col += colorB.rgb * tail * (1.0 + innerGlow);
    col += colorA.rgb * head * 1.6;
  }

  // final tone mapping and clamp for strong festive look
  col = 1.0 - exp(-col * 2.0); // simple soft light amplification
  col = clamp(col, 0.0, 1.0);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Random twinkling sparkles over a solid color",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.0, 0.0, 0.2, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.4 },
    { "NAME": "size", "TYPE": "float", "MIN": 0.1, "MAX": 3.0, "DEFAULT": 0.8 }
  ]
}*/
float hash12(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}
vec2 hash22(vec2 p) {
  return fract(sin(vec2(dot(p, vec2(127.1,311.7)), dot(p, vec2(269.5,183.3)))) * 43758.5453123);
}
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = (RENDERSIZE.y < 2.0);
  vec2 coord = uv;
  if (isLine) {
    coord.y = 0.5;
  }

  // scale controls how many cells across the canvas
  float aspect = RENDERSIZE.x / max(1.0, RENDERSIZE.y);
  float baseScale = mix(8.0, 80.0, density);
  vec2 gridScale = isLine ? vec2(baseScale, 1.0) : vec2(baseScale * aspect, baseScale);

  vec2 grid = coord * gridScale;
  vec2 cell = floor(grid);
  vec2 f = fract(grid);

  // drifting seed so sparkles slowly shift with time along X
  vec2 seedCell = cell + vec2(TIME * speed * 0.07, 0.0);

  vec2 rnd = hash22(seedCell);
  vec2 center = rnd;

  // decide which cells are eligible for a sparkle based on density
  float cellHash = hash12(cell);
  float allow = 1.0 - step(density, cellHash); // 1.0 if cellHash < density

  // temporal twinkle per cell, continuous and smooth
  float phase = sin((TIME * speed * 6.28318) + hash12(cell) * 12.345);
  float twink = smoothstep(0.25, 0.95, 0.5 + 0.5 * phase);

  // radius in cell-local units (0..1)
  float radius = clamp(size * 0.12, 0.02, 0.6);

  // distance from the random center in the cell
  float dist = length(f - center);

  // intensity falloff (soft round sparkles)
  float fall = max(0.0, 1.0 - dist / max(0.0001, radius));
  float intensity = pow(fall, 2.0) * twink * allow;

  // add a small secondary glint for very bright moments
  float glint = pow(max(0.0, 1.0 - abs(dist - radius * 0.2) / (radius * 0.15)), 6.0) * pow(twink, 12.0);
  intensity += glint * allow * 0.6;

  // final color: base color with additive sparkling highlights
  vec3 base = colorA.rgb;
  vec3 spark = colorB.rgb * intensity * 1.6;
  vec3 col = clamp(base + spark, 0.0, 1.0);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Two-color checkerboard sliding sideways",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "scale", "TYPE": "float", "MIN": 1.0, "MAX": 50.0, "DEFAULT": 8.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 1.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);

  // Build tile coordinates so tiles stay roughly square in pixel space.
  vec2 st = vec2(uv.x * scale * aspect, uv.y * scale);

  // When the buffer is a single-pixel-tall roofline, drive the animation along X only.
  if (RENDERSIZE.y < 2.0) {
    st.y = 0.0;
  }

  // Slide the pattern sideways (along X).
  st.x -= TIME * speed;

  const float PI = 3.14159265;

  // Use cosine product to make a checker pattern; cos(...) * cos(...) is >0 in one color, <0 in the other.
  float s = cos(PI * st.x) * cos(PI * st.y);

  // Convert the cosine product into a smooth mix factor.
  // sharpness -> smaller edge threshold -> crisper transition.
  float edge = mix(0.01, 0.0005, clamp(sharpness, 0.0, 1.0));
  float t = smoothstep(-edge, edge, s);

  vec3 col = mix(colorA.rgb, colorB.rgb, t);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "a sunrise slowly rising from the bottom",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.02, 0.02, 0.20, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.00, 0.40, 0.05, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.00, 0.90, 0.30, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "glowRadius", "TYPE": "float", "MIN": 0.01, "MAX": 0.60, "DEFAULT": 0.15 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  // If the buffer is a roofline (very short vertically), run the animation along X instead of Y.
  bool isLine = (RENDERSIZE.y < 2.0);
  float axis = isLine ? uv.x : uv.y;

  // Time base: keep nonzero to avoid exact zero-speed division issues.
  float t = TIME * (0.03 * speed + 0.00001);

  // Smooth periodic rise: sin gives a continuous up-and-down loop.
  // Phase shift so at t=0 the sun starts near the bottom.
  float rise = 0.5 * (1.0 + sin(t * 6.283185 - 1.570796));

  // Sky gradient: mix from night color (colorA) to dawn color (colorB) around the rising horizon.
  float grad = 0.18; // control softness of the horizon band
  float horizonBlend = smoothstep(rise - grad, rise + grad, axis);
  vec3 sky = mix(colorA.rgb, colorB.rgb, horizonBlend);

  // Warm scattering above the horizon to give a sunrise glow.
  float scatter = smoothstep(rise - grad * 2.0, rise + grad * 0.5, axis);
  vec3 warmSky = mix(sky, colorB.rgb, scatter * 0.6);

  // Sun core / glow based on distance from the rising position along the chosen axis.
  float dist = abs(axis - rise);
  float glow = 1.0 - smoothstep(0.0, glowRadius, dist); // 1.0 at center, 0.0 at glowRadius
  glow = pow(glow, 1.0); // keep shape easy to tweak later if desired

  // Strong sun core plus softer outer glow.
  vec3 sunCore = colorC.rgb * (glow * 2.0);
  vec3 sunHalo = colorB.rgb * (glow * 0.8 * (1.0 - dist / max(0.0001, glowRadius)));

  // Combine layers with high contrast for night viewing.
  vec3 color = warmSky + sunHalo + sunCore;
  color = clamp(color, 0.0, 1.0);

  gl_FragColor = vec4(color, 1.0);
}
